// Deathloom fork: which quest reward and vendor gems to take for the build.
// Data: quest-gems.json, generated by tools/gen-quest-gems.py from Exile
// Leveling's game-data export (MIT, (c) 2025 HeartofPhos). Regenerate at each
// league start.

import DATA from './quest-gems.json'

interface QuestOffer {
  quest: string
  id: string
  act: number
  npc: string
  // gem -> class bitmask (pick one)
  take: Record<string, number>
  // gem -> [class bitmask (0 = every class), vendor]
  buy: Record<string, [number, string]>
}

const D = DATA as unknown as { classes: string[], start: Record<string, string[]>, quests: QuestOffer[] }
const QUESTS = D.quests
const CLASSES = D.classes
const START = D.start

export interface WantedGem { name: string, reqLevel: number, support: boolean }

export interface QuestGemStep {
  // reward offer id (the guide's hand-in lines carry it)
  id: string
  quest: string
  act: number
  npc: string
  // the build's gem to pick as the quest reward (null: none of the offers is in the build)
  take: WantedGem | null
  // other offered gems the build uses later (if take is a support, say)
  alsoOffered: string[]
  // the build's gems this quest's vendor sells afterwards
  buy: Array<WantedGem & { vendor: string }>
}

export interface QuestGemPlan {
  className: string
  start: string[]
  steps: QuestGemStep[]
  // build gems no quest reward or vendor gives (transfigured, drop-only, …)
  notFromQuests: WantedGem[]
}

// PoE names supports "X Support" in the game data; PoB calls them "X"
function key (name: string) {
  return name.toLowerCase().replace(/ support$/, '').trim()
}

function classBit (className: string | undefined): number {
  const i = CLASSES.indexOf(className ?? '')
  return i < 0 ? 0 : 1 << i
}

export function planQuestGems (className: string | undefined, wanted: WantedGem[]): QuestGemPlan | null {
  const bit = classBit(className)
  if (!bit) return null
  const byKey = new Map<string, WantedGem>()
  for (const g of wanted) {
    const k = key(g.name)
    const prev = byKey.get(k)
    if (!prev || g.reqLevel < prev.reqLevel) byKey.set(k, g)
  }
  const have = new Set<string>()
  const start = (START[className!] ?? []).filter(Boolean)
  for (const g of start) have.add(key(g))

  const steps: QuestGemStep[] = []
  // a quest's reward offers together: every pick first, then what to buy
  // (Mercy Mission: Nessa's support gem pick before her shop)
  const groups: Array<typeof QUESTS> = []
  for (const q of QUESTS) {
    const last = groups[groups.length - 1]
    // "a1q5" + "a1q5b" = one hand-in with two picks; "a1q2b" / "a1q2" are two separate hand-ins
    if (last && q.id === last[0].id + 'b') last.push(q)
    else groups.push([q])
  }
  for (const group of groups) {
    const picks = new Map<string, { take: WantedGem | null, also: string[] }>()
    for (const q of group) {
      const offered = Object.entries(q.take)
        .filter(([, mask]) => mask & bit)
        .map(([name]) => byKey.get(key(name)))
        .filter((g): g is WantedGem => g != null && !have.has(key(g.name)))
        // skill gems before supports, then the earliest usable
        .sort((a, b) => Number(a.support) - Number(b.support) || a.reqLevel - b.reqLevel)
      const take = offered[0] ?? null
      if (take) have.add(key(take.name))
      picks.set(q.id, { take, also: offered.slice(1).map(g => g.name) })
    }
    for (const q of group) {
      const buy: QuestGemStep['buy'] = []
      for (const [name, [mask, vendor]] of Object.entries(q.buy)) {
        if (mask !== 0 && !(mask & bit)) continue
        const g = byKey.get(key(name))
        if (!g || have.has(key(g.name))) continue
        have.add(key(g.name))
        buy.push({ ...g, vendor })
      }
      buy.sort((a, b) => a.reqLevel - b.reqLevel || a.name.localeCompare(b.name))
      const { take, also } = picks.get(q.id)!
      if (take || buy.length) {
        steps.push({ id: q.id, quest: q.quest, act: q.act, npc: q.npc, take, alsoOffered: also, buy })
      }
    }
  }
  const notFromQuests = [...byKey.values()].filter(g => !have.has(key(g.name)))
  return { className: className!, start, steps, notFromQuests }
}
